using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BMRecord { static long OcclusionBytes=>Directory.GetFiles(Path.ChangeExtension(SceneManager.GetActiveScene().path,null),"*.asset",SearchOption.AllDirectories).Sum(p=>new FileInfo(p).Length);
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B2_FullFloor/";static string O=>R+"/Docs/Review/2026-11-09_B2_FullFloor/";
 public static object Save(){if(StaticOcclusionCulling.isRunning||Application.isPlaying)throw new Exception("Editor still busy");var s=SceneManager.GetActiveScene();foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true))){c.useOcclusionCulling=true;PrefabUtility.RecordPrefabInstancePropertyModifications(c);}EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();return new{saved=!s.isDirty,occlusionRunning=StaticOcclusionCulling.isRunning,occlusionData=OcclusionBytes};}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved B2 required");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var before=JArray.Parse(File.ReadAllText(H+"C02_before.json"));var changes=new List<object>();var missing=new List<string>();foreach(var p in before){GlobalObjectId.TryParse((string)p["id"],out var id);var t=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id) as Transform;if(!t){missing.Add((string)p["name"]);continue;}var pos=new Vector3((float)p["pos"][0],(float)p["pos"][1],(float)p["pos"][2]);var scale=new Vector3((float)p["scale"][0],(float)p["scale"][1],(float)p["scale"][2]);var rot=new Quaternion((float)p["rot"][0],(float)p["rot"][1],(float)p["rot"][2],(float)p["rot"][3]);bool moved=Vector3.Distance(pos,t.localPosition)>.0001f||Vector3.Distance(scale,t.localScale)>.0001f||Quaternion.Angle(rot,t.localRotation)>.01f;bool active=(bool)p["active"]!=t.gameObject.activeSelf;if(moved||active)changes.Add(new{t.name,moved,activeChanged=active,active=t.gameObject.activeSelf});}
 var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));var placements=new List<object>();foreach(var p in plan["placements"]){var t=all.Single(t=>t.name==(string)p["name"]);var target=new Vector3((float)p["position"][0],(float)p["position"][1],(float)p["position"][2]);placements.Add(new{name=t.name,asset=(string)p["asset"],localPosition=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},worldPosition=new[]{t.position.x,t.position.y,t.position.z},yaw=t.localEulerAngles.y,positionError=Vector3.Distance(target,t.localPosition),yawError=Mathf.Abs(Mathf.DeltaAngle((float)p["yaw"],t.localEulerAngles.y))});}
 var result=new{scene=s.path,saved=!s.isDirty,C02OriginalTransforms=before.Count,C02Missing=missing,C02Changes=changes,newPlacements=placements,occlusionBytes=OcclusionBytes,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,Application.runInBackground};File.WriteAllText(O+"final_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{C02OriginalTransforms=before.Count,missing=missing.Count,changed=changes.Count,placements=placements.Count,OcclusionBytes,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled};}
}
